content.css:
/* ========================================================================== */
/* BFUSION Resource Heatmap — Base Structural Layout Rules                    */
/* ========================================================================== */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: #FFFFFF;
  position: relative;
  color: #242424;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
.bfusion-rh {
  display: flex;
  flex-direction: column;
  padding-bottom: 24px;
  /* license badge clear-zone */
}
/* Header bar (title + subtitle + info button) */
.rh-header {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 10px 16px 6px 16px;
  border-bottom: 1px solid #E5E7EB;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
  position: relative;
}
.rh-header__titles {
  flex: 1 1 auto;
  min-width: 0;
}
.rh-header__title {
  font-weight: 700;
  color: #242424;
  letter-spacing: 0.1px;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rh-header__subtitle {
  margin-top: 2px;
  color: #6C757D;
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rh-header__info {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid #E5E7EB;
  background: #fff;
  color: #6C757D;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  transition: all 0.15s ease;
}
.rh-header__info:hover {
  color: #fff;
  background: #E8612A;
  border-color: #E8612A;
  transform: scale(1.05);
}
.rh-header__info-pop {
  position: absolute;
  top: calc(100% + 6px);
  right: 12px;
  z-index: 30;
  width: 280px;
  max-width: calc(100% - 24px);
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
  padding: 12px 14px;
  color: #242424;
  line-height: 1.45;
}
.rh-header__info-pop ul {
  margin: 6px 0 0 0;
  padding-left: 18px;
}
.rh-header__info-pop ul li {
  margin: 3px 0;
  color: #6C757D;
}
.rh-info-pop__title {
  font-weight: 700;
  color: #242424;
  margin-bottom: 4px;
  padding-bottom: 4px;
  border-bottom: 2px solid #E8612A;
}
.rh-info-pop__desc {
  color: #6C757D;
}
.rh-info-pop__howto {
  margin-top: 8px;
  font-weight: 600;
  color: #6C757D;
}
/* What-if threshold slider row */
.rh-controls {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 16px;
  border-bottom: 1px solid #E5E7EB;
  background: #F8F9FB;
}
.rh-controls__label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #6C757D;
  white-space: nowrap;
}
.rh-controls__slider {
  flex: 0 1 220px;
  min-width: 90px;
  accent-color: var(--rh-insight-accent, #E8612A);
  cursor: pointer;
}
.rh-controls__readout {
  font-size: 11px;
  font-weight: 700;
  color: #1F2A44;
  font-variant-numeric: tabular-nums;
  min-width: 38px;
}
/* Body row: chart + insight strip + insight panel */
.rh-body {
  flex: 1 1 auto;
  display: flex;
  flex-direction: row;
  min-height: 0;
  overflow: hidden;
}
.rh-chart-col {
  flex: 1 1 auto;
  min-width: 0;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
/* Legend chips */
.rh-legend {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  padding: 8px 16px 4px 16px;
}
.rh-legend__title {
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #6C757D;
  margin-right: 4px;
}
.rh-legend__chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 9px;
  border-radius: 999px;
  border: 1px solid #E5E7EB;
  background: #fff;
  color: #242424;
  font-size: inherit;
  font-family: inherit;
  cursor: pointer;
  transition: all 0.15s ease;
}
.rh-legend__chip:hover {
  border-color: #E8612A;
  box-shadow: 0 2px 6px rgba(15, 23, 42, 0.08);
}
.rh-legend__chip--active {
  border-color: #E8612A;
  background: rgba(232, 97, 42, 0.08);
  font-weight: 600;
}
.rh-legend__chip--dim {
  opacity: 0.45;
}
.rh-legend__swatch {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  border: 1px solid rgba(0, 0, 0, 0.08);
}
/* Scrollable heatmap area */
.rh-chart-scroll {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: 4px 8px 8px 8px;
}
.rh-cell rect {
  transition: filter 0.12s ease;
}
.rh-cell:hover rect {
  filter: brightness(0.94) drop-shadow(0 2px 5px rgba(15, 23, 42, 0.25));
}
.rh-collabel:hover,
.rh-rowlabel:hover {
  fill: #E8612A;
}
/* ========================================================================== */
/* Insight Panel (right-side) — collapsed strip + expanded panel             */
/* ========================================================================== */
.rh-insight-strip {
  flex: 0 0 auto;
  width: 24px;
  background: #F8F9FB;
  border-left: 1px solid #E5E7EB;
  color: #6C757D;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
}
.rh-insight-strip__arrow {
  font-size: 11px;
  color: var(--rh-insight-accent, #E8612A);
  line-height: 1;
}
.rh-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  letter-spacing: 2px;
  font-weight: 600;
  color: #6C757D;
  text-transform: uppercase;
}
.rh-insight-strip:hover,
.rh-insight-strip:focus {
  background: #FFFFFF;
  color: #242424;
  outline: none;
}
.rh-insight-panel {
  flex: 0 0 250px;
  max-width: 320px;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
  border-left: 1px solid #E5E7EB;
  display: flex;
  flex-direction: column;
  padding: 12px 12px 16px 12px;
  overflow-y: auto;
  font-size: var(--rh-insight-font, 11px);
  color: #242424;
  gap: 10px;
}
.rh-insight__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
  padding-bottom: 6px;
  border-bottom: 2px solid var(--rh-insight-accent, #E8612A);
}
.rh-insight__title {
  font-size: var(--rh-insight-header-font, 12px);
  font-weight: 700;
  color: #242424;
  letter-spacing: 0.2px;
}
.rh-insight__subtitle {
  font-size: calc(var(--rh-insight-font, 11px) - 1px);
  color: #6C757D;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 55%;
}
.rh-insight__scope-reset {
  align-self: flex-start;
  border: 1px solid var(--rh-insight-accent, #E8612A);
  color: var(--rh-insight-accent, #E8612A);
  background: #fff;
  border-radius: 999px;
  font-size: calc(var(--rh-insight-font, 11px) - 1px);
  font-family: inherit;
  padding: 2px 9px;
  cursor: pointer;
  transition: all 0.15s ease;
}
.rh-insight__scope-reset:hover {
  background: var(--rh-insight-accent, #E8612A);
  color: #fff;
}
.rh-insight__kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}
.rh-kpi {
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-left: 3px solid var(--rh-kpi-color, #E8612A);
  border-radius: 6px;
  padding: 6px 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.rh-kpi:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 10px rgba(15, 23, 42, 0.08);
}
.rh-kpi__value {
  font-size: calc(var(--rh-insight-font, 11px) + 4px);
  font-weight: 700;
  color: var(--rh-kpi-color, #242424);
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rh-kpi__label {
  font-size: calc(var(--rh-insight-font, 11px) - 1px);
  color: #6C757D;
}
.rh-insight__section {
  margin-top: 4px;
}
.rh-insight__section-title {
  font-weight: 600;
  color: #6C757D;
  font-size: calc(var(--rh-insight-font, 11px) - 1px);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}
/* Stacked distribution health bar */
.rh-insight__health {
  display: flex;
  height: 10px;
  border-radius: 999px;
  overflow: hidden;
  background: #E5E7EB;
}
.rh-insight__health-seg {
  flex-basis: 0;
  min-width: 3px;
}
.rh-insight__health-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 10px;
  margin-top: 6px;
  font-size: calc(var(--rh-insight-font, 11px) - 1px);
  color: #6C757D;
}
.rh-insight__health-legend span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.rh-insight__health-legend i {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  display: inline-block;
}
.rh-insight__smart {
  margin: 0;
  padding-left: 16px;
}
.rh-insight__smart li {
  margin: 4px 0;
  line-height: 1.4;
  color: #242424;
}
.rh-insight__smart strong {
  font-weight: 700;
}
.rh-insight__list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.rh-insight__list li {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border-radius: 4px;
  margin-bottom: 2px;
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
}
.rh-insight__dot {
  flex: 0 0 auto;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.95);
}
.rh-insight__name {
  flex: 1 1 auto;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rh-insight__val {
  flex: 0 0 auto;
  font-weight: 600;
  color: #242424;
  font-variant-numeric: tabular-nums;
}
/* Operational call banner */
.rh-insight__call {
  margin-top: auto;
  border-radius: 6px;
  padding: 8px 10px;
  border: 1px solid #E5E7EB;
}
.rh-insight__call--warn {
  background: rgba(239, 68, 68, 0.06);
  border-color: rgba(239, 68, 68, 0.25);
}
.rh-insight__call--warn .rh-insight__call-value {
  color: #DC2626;
}
.rh-insight__call--ok {
  background: rgba(34, 197, 94, 0.06);
  border-color: rgba(34, 197, 94, 0.25);
}
.rh-insight__call--ok .rh-insight__call-value {
  color: #15803D;
}
.rh-insight__call-label {
  font-size: calc(var(--rh-insight-font, 11px) - 2px);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #6C757D;
  margin-bottom: 2px;
}
.rh-insight__call-value {
  font-weight: 600;
}
/* Insight panel visibility states */
.rh-body--insight-collapsed .rh-insight-panel {
  display: none;
}
.rh-body--insight-hidden .rh-insight-panel,
.rh-body--insight-hidden .rh-insight-strip {
  display: none;
}
/* ========================================================================== */
/* Responsive width classes                                                   */
/* ========================================================================== */
.rh-medium .rh-insight-panel {
  flex-basis: 220px;
}
.rh-medium .rh-controls__slider {
  flex-basis: 140px;
}
.rh-narrow .rh-insight-panel {
  position: absolute;
  right: 24px;
  top: 0;
  bottom: 0;
  width: 240px;
  z-index: 25;
  box-shadow: -6px 0 18px rgba(15, 23, 42, 0.1);
}
.rh-narrow .rh-header__title {
  font-size: 12px !important;
}
.rh-narrow .rh-controls__slider {
  flex-basis: 100px;
}
/* ========================================================================== */
/* Responsive Landing Page Framework                                         */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: #242424;
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: #666666;
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #444444;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: #707070;
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
/* ========================================================================== */
/* Empty Data State (cross-filter excluded everything)                        */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: #94a3b8;
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
